<template>
  <section class="templateLibrary"><header class="pageHeading templateHeading"><div><h1>制作模板</h1><p>把输入、镜头结构和参考版本关系保存为可复用的制作方法。</p></div><div class="libraryActions"><el-button :disabled="!store.loaded || store.busy" @click="edit()">新增制作模板</el-button><el-button :disabled="!store.loaded || store.busy" @click="beginCapture">从制作单元保存</el-button><el-button @click="importInput?.click()">导入制作模板</el-button><el-button :loading="store.loading" :disabled="store.busy" @click="reload">刷新模板</el-button><input ref="importInput" class="fileInput" type="file" accept=".json,application/json" aria-label="导入制作模板文件" @change="importFile" /></div></header>
    <p v-if="error || store.error" ref="errorBox" class="errorText" role="alert" tabindex="-1">{{ error || store.error }}{{ !store.loaded ? ' · 个人库读取成功后才能保存。' : '' }}</p><p v-if="status" class="statusText" role="status">{{ status }}</p>
    <div class="templateToolbar"><nav aria-label="制作模板范围"><button v-for="item in scopes" :key="item.id" :aria-pressed="scope === item.id" :class="{ active: scope === item.id }" @click="scope = item.id">{{ item.label }}</button></nav><label>搜索制作模板<input v-model="query" type="search" aria-label="搜索制作模板" placeholder="标题、标签或用途" /></label></div>
    <div v-if="filtered.length" class="templateWorkspace"><section class="templateList" aria-label="制作模板列表"><button v-for="entry in filtered" :key="entry.id" :aria-pressed="current?.id === entry.id" :class="{ selected: current?.id === entry.id }" @click="selectedId = entry.id"><strong>{{ entry.definition.title }}</strong><span>{{ entry.definition.description }}</span><small>{{ entry.origin === 'builtin' ? '内置结构范例' : '我的模板' }} · {{ entry.definition.example.shots.length }} 个镜头{{ entry.favorite ? ' · 已收藏' : '' }}</small></button></section><section v-if="current" class="selectedTemplate" aria-label="制作模板详情"><h2>{{ current.definition.title }}</h2><p class="statusText">{{ current.origin === 'builtin' ? '内置范例只读，可另存并修改；不包含生成成品。' : current.archived ? '已归档，可恢复后复用。' : '个人制作模板 · 保存在本机' }}</p><div class="libraryActions"><el-button v-if="!current.archived" type="primary" @click="openApply">应用到项目</el-button><el-button v-if="!current.archived" :disabled="!store.loaded || store.busy" @click="edit(current)">{{ current.origin === 'builtin' ? '另存并修改' : '编辑制作模板' }}</el-button><el-button :disabled="!store.loaded || store.busy || current.archived" :aria-pressed="current.favorite" @click="favorite">{{ current.favorite ? '取消收藏模板' : '收藏模板' }}</el-button><el-button @click="openExport">导出制作模板</el-button><el-button v-if="current.origin === 'personal'" :disabled="!store.loaded || store.busy" @click="archive">{{ current.archived ? '恢复模板' : '归档模板' }}</el-button></div><productionTemplateDetail :definition="current.definition" /></section></div><p v-else class="emptyTemplates">没有匹配的制作模板，可调整搜索范围或新增模板。</p>
    <productionTemplateEditor v-model="editing" :entryId="editingId" :seed="editingSeed" @saved="saved" /><productionTemplateApply v-model="applying" :definition="applyDefinition" />
    <el-dialog v-model="exporting" title="检查制作模板导出内容" width="min(800px, 96vw)" appendToBody><div class="templateExport"><p>以下为本次实际导出内容。默认清空变量默认值和样例私有内容，并移除模型编号提示；请检查标题、用途、流程及输入说明中的私人信息。</p><div class="exportOptions"><label><input v-model="exportOptions.includeDefaults" type="checkbox" />包含变量默认值</label><label><input v-model="exportOptions.includeExampleContent" type="checkbox" />包含样例名称、剧情、提示词及参考文字</label><label><input v-model="exportOptions.includeModelHints" type="checkbox" />包含模型编号提示</label></div><template v-if="portable"><h2>{{ portable.template.title }}</h2><productionTemplateDetail :definition="portable.template" /><p>不包含应用渠道配置、凭据、原项目路径与编号、媒体文件或收藏。重新导入会创建独立模板。</p><el-button type="primary" @click="download">下载制作模板文件</el-button></template></div></el-dialog>
    <el-dialog v-model="capturing" title="从制作单元保存模板" width="min(760px, 96vw)" appendToBody :closeOnClickModal="!captureBusy" :showClose="!captureBusy"><div class="templateCapture"><p>提取镜头结构与参考版本关系；生成结果和媒体文件保留在原项目。</p><workspacePicker v-model="captureDirectory" :disabled="captureBusy" /><p class="statusText">{{ captureDirectory || '请选择来源项目' }}</p><p v-if="captureError" class="errorText" role="alert">{{ captureError }}</p><label>来源制作单元<select v-model="captureSequence" :disabled="captureBusy" aria-label="来源制作单元"><option value="">请选择</option><option v-for="sequence in captureProject?.sequences.filter(item => !item.archived)" :key="sequence.sequenceId" :value="sequence.sequenceId">{{ sequence.name }}</option></select></label><p v-if="sourceSummary">{{ sourceSummary.shots }} 个镜头 · {{ sourceSummary.adopted }} 个已采用 · {{ sourceSummary.exports }} 次已完成导出</p><p class="statusText">也可保存尚未完成的结构草稿。没有媒体候选的镜头使用下方明确指定的类型，保存前会提示核对。</p><label>无候选时的镜头类型<select v-model="captureOptions.fallbackMediaType" aria-label="无候选时的镜头类型"><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></label><fieldset :disabled="captureBusy"><legend>选择保留的原内容，默认均不保留</legend><label v-for="item in captureToggles" :key="item.key" class="toggle"><input v-model="captureOptions[item.key]" type="checkbox" />{{ item.label }}</label></fieldset><el-button :disabled="captureBusy || !captureProject || !captureSequence" @click="capture">提取并检查模板草稿</el-button></div></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from "vue";
import axios from "axios";
import { ElMessageBox } from "element-plus";
import { exportProductionTemplate, productionTemplateExportSchema, type ProductionTemplate, type ProductionTemplateEntry } from "@toonflow/server/productionTemplates";
import type { ProjectRecord } from "@toonflow/server/production";
import productionTemplateEditor from "./productionTemplateEditor.vue";
import productionTemplateApply from "./productionTemplateApply.vue";
import productionTemplateDetail from "./productionTemplateDetail.vue";
import workspacePicker from "@/pages/home/workspacePicker.vue";
import { useWorkspaceStore } from "@/stores/workspace";
import { productionTemplateError, useProductionTemplateLibraryStore } from "@/stores/productionTemplates";
const store = useProductionTemplateLibraryStore(); const workspace = useWorkspaceStore(); const headers = { "x-toonflow-workspace": "1" };
const scopes = [{ id: "all", label: "全部模板" }, { id: "personal", label: "我的模板" }, { id: "favorites", label: "收藏" }, { id: "archived", label: "已归档" }];
const scope = ref("all"); const query = ref(""); const selectedId = ref(""); const error = ref(""); const status = ref(""); const errorBox = ref<HTMLElement>(); const importInput = ref<HTMLInputElement>();
const filtered = computed(() => store.entries.filter(entry => (scope.value === "archived" ? entry.archived : !entry.archived) && (scope.value !== "personal" || entry.origin === "personal") && (scope.value !== "favorites" || entry.favorite) && `${entry.definition.title} ${entry.definition.description} ${entry.definition.tags.join(" ")}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())));
const current = computed(() => filtered.value.find(entry => entry.id === selectedId.value) ?? filtered.value[0]);
async function fail(cause: unknown) { error.value = productionTemplateError(cause); await nextTick(); errorBox.value?.focus(); }
async function reload() { error.value = ""; try { await store.load(); } catch (cause) { await fail(cause); } }
onMounted(() => { void reload(); });
const editing = ref(false); const editingId = ref<string>(); const editingSeed = ref<ProductionTemplate>(); const applying = ref(false); const applyDefinition = ref<ProductionTemplate>();
function edit(entry?: ProductionTemplateEntry) { editingId.value = entry?.origin === "personal" ? entry.id : undefined; editingSeed.value = entry && JSON.parse(JSON.stringify(entry.definition)); editing.value = true; }
function saved(id: string) { query.value = ""; scope.value = "personal"; selectedId.value = id; status.value = "制作模板已保存"; error.value = ""; }
function openApply() { if (!current.value) return; applyDefinition.value = JSON.parse(JSON.stringify(current.value.definition)); applying.value = true; }
async function favorite() { const entry = current.value; if (!entry) return; try { await store.update({ type: "favorite", id: entry.id, value: !entry.favorite }); error.value = ""; } catch (cause) { await fail(cause); } }
async function archive() { const entry = current.value; if (!entry || entry.origin !== "personal") return; const revision = store.library.revision; if (!entry.archived && !await ElMessageBox.confirm("归档后内容与收藏保留，可以恢复。", `归档「${entry.definition.title}」`, { confirmButtonText: "归档", cancelButtonText: "保留" }).then(() => true, () => false)) return; try { await store.update({ type: "archive", id: entry.id, value: !entry.archived }, revision); status.value = entry.archived ? "制作模板已恢复" : "制作模板已归档"; } catch (cause) { await fail(cause); } }
const exporting = ref(false); const exportDefinition = ref<ProductionTemplate>(); const exportOptions = ref({ includeDefaults: false, includeExampleContent: false, includeModelHints: false });
const portable = computed(() => exportDefinition.value ? exportProductionTemplate(exportDefinition.value, exportOptions.value) : undefined);
function openExport() { if (!current.value) return; exportDefinition.value = JSON.parse(JSON.stringify(current.value.definition)); exportOptions.value = { includeDefaults: false, includeExampleContent: false, includeModelHints: false }; exporting.value = true; }
function download() { const value = portable.value; if (!value) return; const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: "application/json" })); const link = document.createElement("a"); link.href = url; link.download = `${Array.from(value.template.title).slice(0, 80).join("").replace(/[<>:"/\\|?*\u0000-\u001f]/g, "").replace(/[. ]+$/, "") || "template"}.zeromuProductionTemplate.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); status.value = "制作模板文件已准备下载，内容按本次预览导出"; }
async function importFile(event: Event) { const element = event.target as HTMLInputElement; const file = element.files?.[0]; element.value = ""; if (!file) return; try { if (file.size > 8 * 1024 * 1024) throw new Error("制作模板文件不能超过 8 MB"); const parsed = productionTemplateExportSchema.safeParse(JSON.parse(await file.text())); if (!parsed.success) throw new Error("文件不是支持的零幕制作模板格式，或内容关系校验未通过"); editingId.value = undefined; editingSeed.value = parsed.data.template; editing.value = true; } catch (cause) { await fail(cause instanceof SyntaxError ? new Error("制作模板文件不是有效的 JSON，请保留原件并重新导出") : cause); } }
const capturing = ref(false); const captureDirectory = ref(""); const captureProject = ref<ProjectRecord | null>(null); const captureSequence = ref(""); const captureBusy = ref(false); const captureError = ref(""); let captureEpoch = 0;
const captureOptions = ref({ includeNames: false, includeStory: false, includePrompts: false, includeAssetText: false, includeModelHints: false, fallbackMediaType: "image" as "image" | "video" | "audio" });
const captureToggles = [{ key: "includeNames", label: "保留制作单元、镜头、素材名称与引用用途" }, { key: "includeStory", label: "保留剧情与对白" }, { key: "includePrompts", label: "保留来源候选的生成提示词" }, { key: "includeAssetText", label: "保留参考素材的文字与说明" }, { key: "includeModelHints", label: "保留来源候选的模型编号提示" }] as const;
const sourceSummary = computed(() => { const project = captureProject.value; const sequence = project?.sequences.find(item => item.sequenceId === captureSequence.value); return sequence ? { shots: sequence.shotIds.length, adopted: project!.shots.filter(shot => sequence.shotIds.includes(shot.shotId) && shot.adoptedCandidateId).length, exports: project!.exports.filter(item => item.edit.sequenceId === sequence.sequenceId && item.status === "completed").length } : undefined; });
function beginCapture() { captureOptions.value = { includeNames: false, includeStory: false, includePrompts: false, includeAssetText: false, includeModelHints: false, fallbackMediaType: "image" }; capturing.value = true; captureDirectory.value = workspace.project?.directory ?? ""; void loadCapture(); }
watch(captureDirectory, () => { if (capturing.value) void loadCapture(); });
async function loadCapture() { const path = captureDirectory.value; const requestEpoch = ++captureEpoch; captureProject.value = null; captureSequence.value = ""; captureError.value = ""; if (!path) return; captureBusy.value = true; try { const { data } = await axios.get<{ data: { project: ProjectRecord | null } }>("/api/production/get", { params: { directory: path }, headers }); if (requestEpoch !== captureEpoch) return; captureProject.value = data.data.project; if (!data.data.project?.sequences.some(item => !item.archived)) captureError.value = "此项目没有可提取的活动制作单元"; } catch (cause) { if (requestEpoch === captureEpoch) captureError.value = productionTemplateError(cause); } finally { if (requestEpoch === captureEpoch) captureBusy.value = false; } }
async function capture() { const project = captureProject.value; const path = captureDirectory.value; if (!project || !captureSequence.value) return; captureBusy.value = true; try { const { data } = await axios.post<{ data: { definition: ProductionTemplate; warnings: string[] } }>("/api/productionTemplates/capture", { directory: path, expectedRevision: project.revision, sequenceId: captureSequence.value, options: captureOptions.value }, { headers }); if (path !== captureDirectory.value) return; editingId.value = undefined; editingSeed.value = data.data.definition; capturing.value = false; editing.value = true; status.value = data.data.warnings.join("；") || "已提取独立模板草稿，请检查后保存"; } catch (cause) { captureError.value = productionTemplateError(cause); } finally { captureBusy.value = false; } }
</script>

<style scoped lang="scss">
.templateLibrary { min-height: 0; min-width: 0; display: flex; flex-direction: column; flex: 1; font-size: 13px; line-height: 1.7; .templateHeading { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px; } .libraryActions { display: flex; gap: 8px; flex-wrap: wrap; .el-button { margin-left: 0; } } .fileInput { display: none; } .errorText { color: var(--el-color-danger); overflow-wrap: anywhere; } .statusText { color: var(--homeMuted); font-size: 12px; } .templateToolbar { display: flex; align-items: end; justify-content: space-between; gap: 16px; border-bottom: 1px solid var(--homeLine); padding-bottom: 16px; nav { display: flex; gap: 4px; flex-wrap: wrap; } button { min-height: 36px; padding: 8px 12px; color: var(--homeMuted); border: 1px solid transparent; border-radius: 8px; background: transparent; &.active { color: var(--homeAccent); border-color: var(--homeLine); background: var(--homeSurface); } } label { display: flex; flex-direction: column; gap: 4px; color: var(--homeMuted); font-size: 12px; } input { padding: 9px; color: var(--homeText); background: var(--homeSurface); border: 1px solid var(--homeLine); border-radius: 6px; font: inherit; min-width: 0; } } .templateWorkspace { flex: 1; display: grid; grid-template-columns: minmax(230px, 30%) minmax(0, 1fr); min-height: 0; gap: 24px; padding-top: 20px; } .templateList { overflow: auto; min-width: 0; padding-right: 4px; button { width: 100%; text-align: left; display: flex; flex-direction: column; gap: 8px; border: 1px solid transparent; color: var(--homeText); background: transparent; border-radius: 10px; padding: 16px; margin-bottom: 8px; overflow-wrap: anywhere; strong { font-size: 15px; } span { color: var(--homeMuted); font-size: 12px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; } small { color: var(--homeAccent); } &.selected { background: var(--homeSurface); border-color: var(--homeLine); } } } .selectedTemplate { overflow: auto; min-width: 0; border-radius: 12px; padding: 28px; background: var(--homeSurface); h2 { margin: 0 0 8px; font-size: 24px; overflow-wrap: anywhere; } } .emptyTemplates { padding-block: 40px; color: var(--homeMuted); } @media(max-width:720px) { .templateToolbar { align-items: stretch; flex-direction: column; } .templateWorkspace { flex: 0 0 auto; grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(140px, min(30dvh, 240px)) auto; gap: 16px; } .selectedTemplate { padding: 20px; } .el-button, .templateToolbar button, .templateToolbar input { min-height: 44px; } } }
.templateExport, .templateCapture { font-size: 13px; line-height: 1.8; overflow-wrap: anywhere; .exportOptions { padding-block: 12px; display: grid; gap: 10px; } .toggle, .exportOptions label { display: flex; gap: 8px; align-items: center; min-height: 36px; } .errorText { color: var(--el-color-danger); } .statusText { font-size: 12px; color: var(--el-text-color-secondary); } label:not(.toggle) { display: flex; flex-direction: column; gap: 6px; margin-bottom: 12px; } .exportOptions label { flex-direction: row; } select { width: 100%; padding: 9px; color: var(--el-text-color-primary); background: var(--el-bg-color); border: 1px solid var(--el-border-color); border-radius: 6px; } fieldset { border: 0; padding: 0; margin: 12px 0; } @media(max-width:600px) { .toggle, .exportOptions label, select, .el-button { min-height: 44px; } } }
</style>
